begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('f1060000-0000-0000-0000-000000000001','frontdesk-owner@test.invalid'),('f1060000-0000-0000-0000-000000000002','frontdesk-viewer@test.invalid');
insert into public.tenants(id,name,slug)values('f1061000-0000-0000-0000-000000000001','Frontdesk QA','frontdesk-106');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f1061000-0000-0000-0000-000000000001','f1060000-0000-0000-0000-000000000001','owner'),('f1061000-0000-0000-0000-000000000001','f1060000-0000-0000-0000-000000000002','member');
insert into public.properties(id,tenant_id,name,property_type,timezone)values('f1062000-0000-0000-0000-000000000001','f1061000-0000-0000-0000-000000000001','Frontdesk Hotel','hotel','UTC'),('f1062000-0000-0000-0000-000000000002','f1061000-0000-0000-0000-000000000001','Other Hotel','hotel','UTC');
select 'f1062000-0000-0000-0000-000000000001'::uuid pid,'f1061000-0000-0000-0000-000000000001'::uuid tenant,'f1063000-0000-0000-0000-000000000001'::uuid type \gset
insert into public.accommodation_types(id,tenant_id,property_id,name,max_occupancy,base_rate)values(:'type',:'tenant',:'pid','Deluxe',3,100);
insert into public.accommodation_units(id,tenant_id,property_id,type_id,name,housekeeping_status)
select ('f1064000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,:'tenant',:'pid',:'type','Room '||n,case when n=2 then 'dirty'else 'clean'end from generate_series(1,6)n;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1060000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.r1',public.frontdesk_create_whatsapp(:'pid','INR','f1065000-0000-0000-0000-000000000001','Guest 1','+15550001061',null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000001','', 'direct',100)::text,true);
select set_config('test.r2',public.frontdesk_create_whatsapp(:'pid','INR','f1065000-0000-0000-0000-000000000002','Guest 2','+15550001062',null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000002','', 'direct',100)::text,true);
select set_config('test.r3',public.frontdesk_create_whatsapp(:'pid','INR','f1065000-0000-0000-0000-000000000003','Guest 3','+15550001063',null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000003','', 'direct',100)::text,true);
select set_config('test.g1',(select guest_id::text from public.reservations where id=current_setting('test.r1')::uuid),true);
select lives_ok(format('select public.frontdesk_edit_guest(%L,%L,1,''Corrected Guest'',''+15550001061'',''corrected@example.test'',''Spelling correction'')',:'pid',current_setting('test.g1')),'guest details can be corrected after booking');
select is((select full_name from public.guests where id=current_setting('test.g1')::uuid),'Corrected Guest','corrected name is stored');
select is((select profile_version from public.guests where id=current_setting('test.g1')::uuid),2,'profile version advances');
select throws_ok(format('select public.frontdesk_edit_guest(%L,%L,1,''Stale Guest'',''+15550001061'',null,''Stale correction'')',:'pid',current_setting('test.g1')),'40001',null,'stale guest edit cannot overwrite correction');
select throws_ok(format('select public.frontdesk_edit_guest(%L,%L,2,''Corrected Guest'',''+15550001069'',null,''Phone correction'')',:'pid',current_setting('test.g1')),'22023',null,'phone correction requires explicit confirmation');
select throws_ok(format('select public.frontdesk_edit_guest(%L,%L,2,''Corrected Guest'',''+15550001061'',''bad-email'',''Email correction'')',:'pid',current_setting('test.g1')),'22023',null,'invalid guest email is rejected');
select throws_ok(format('select public.frontdesk_edit_guest(''f1062000-0000-0000-0000-000000000002'',%L,2,''Wrong hotel'',''+15550001061'',null,''Wrong hotel correction'')',current_setting('test.g1')),'42501',null,'guest edit cannot mix hotel and profile');
select set_config('test.items',jsonb_build_array(jsonb_build_object('id',current_setting('test.r1'),'version',1),jsonb_build_object('id',current_setting('test.r2'),'version',1),jsonb_build_object('id',current_setting('test.r3'),'version',99))::text,true);
select set_config('test.batch',public.frontdesk_bulk_action(:'pid','f1066000-0000-0000-0000-000000000001','check_in',current_setting('test.items')::jsonb)::text,true);
select is((select count(*)::int from jsonb_array_elements(current_setting('test.batch')::jsonb)x where(x->>'success')::boolean),1,'bulk check-in completes the ready stay only');
select is((select status from public.reservations where id=current_setting('test.r1')::uuid),'checked_in','ready guest is in house');
select is((select status from public.reservations where id=current_setting('test.r2')::uuid),'confirmed','dirty room remains confirmed');
select is((select status from public.reservations where id=current_setting('test.r3')::uuid),'confirmed','stale selection remains unchanged');
select ok(exists(select 1 from jsonb_array_elements(current_setting('test.batch')::jsonb)x where x->>'error'like '%clean%'),'dirty room result explains the blocker');
select is(public.frontdesk_bulk_action(:'pid','f1066000-0000-0000-0000-000000000001','check_in',current_setting('test.items')::jsonb),current_setting('test.batch')::jsonb,'retry returns the recorded batch result');
select is((select count(*)::int from public.reservation_events where reservation_id=current_setting('test.r1')::uuid and event_type='checked_in'),1,'batch retry cannot repeat check-in events');
select throws_ok(format('select public.frontdesk_bulk_action(%L,''f1066000-0000-0000-0000-000000000001'',''check_out'',%L::jsonb)',:'pid',current_setting('test.items')),'40001',null,'batch request cannot be reused with another operation');
select throws_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''cancel'',%L::jsonb)',:'pid',current_setting('test.items')),'22023',null,'bulk action cannot perform arbitrary mutations');
select throws_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''check_in'',%L::jsonb)',:'pid',jsonb_build_array(jsonb_build_object('id',current_setting('test.r2'),'version',1),jsonb_build_object('id',current_setting('test.r2'),'version',1))::text),'22023',null,'duplicate stays are rejected');
select throws_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''check_in'',%L::jsonb)','f1062000-0000-0000-0000-000000000002',current_setting('test.items')),'42501',null,'cross-hotel batches are rejected before actions');
select throws_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''check_in'',''[{"id":"bad","version":1}]'')',:'pid'),'22023',null,'malformed batch items are rejected');
select set_config('test.checkout',public.frontdesk_bulk_action(:'pid','f1066000-0000-0000-0000-000000000002','check_out',jsonb_build_array(jsonb_build_object('id',current_setting('test.r1'),'version',2)))::text,true);
select ok(not(current_setting('test.checkout')::jsonb#>>'{0,success}')::boolean,'bulk checkout cannot bypass folio settlement');
select is((select status from public.reservations where id=current_setting('test.r1')::uuid),'checked_in','unsettled guest remains in house');
select public.post_room_charges(current_setting('test.r1')::uuid);
select public.collect_folio_payment((select id from public.folios where reservation_id=current_setting('test.r1')::uuid),100,'cash');
select lives_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''check_out'',jsonb_build_array(jsonb_build_object(''id'',%L,''version'',2)))',:'pid',current_setting('test.r1')),'settled group checkout succeeds');
select is((select status from public.reservations where id=current_setting('test.r1')::uuid),'checked_out','checkout records final state');
select is((select housekeeping_status from public.accommodation_units where name='Room 1'and property_id=:'pid'),'dirty','group checkout marks room dirty');
select is((select count(*)::int from public.tasks where reservation_id=current_setting('test.r1')::uuid and kind='housekeeping'),1,'group checkout creates one cleaning task');
select set_config('test.walk',public.frontdesk_walk_in(:'pid','INR','f1067000-0000-0000-0000-000000000001',null,'Walk-in Guest',null,null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000004','',100)::text,true);
select is(current_setting('test.walk')::jsonb->>'status','checked_in','walk-in books and checks in with one command');
select is((select source from public.reservations where id=(current_setting('test.walk')::jsonb->>'id')::uuid),'walk_in','walk-in source is recorded');
select is(public.frontdesk_walk_in(:'pid','INR','f1067000-0000-0000-0000-000000000001',null,'Walk-in Guest',null,null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000004','',100)->>'id',current_setting('test.walk')::jsonb->>'id','walk-in retry reuses the same stay');
select throws_ok(format('select public.frontdesk_walk_in(%L,''INR'',gen_random_uuid(),null,''Future walk-in'',null,null,%L,current_date+1,current_date+2,1,0,null,null,'''',100)',:'pid',:'type'),'22023',null,'walk-in must arrive today in hotel time');
select throws_ok(format('select public.frontdesk_walk_in(%L,''INR'',''f1065000-0000-0000-0000-000000000002'',null,''Different request'',null,null,%L,current_date,current_date+1,1,0,null,null,'''',100)',:'pid',:'type'),'40001',null,'walk-in cannot reuse a direct booking request');
select set_config('test.returnwalk',public.frontdesk_walk_in(:'pid','INR','f1067000-0000-0000-0000-000000000003',current_setting('test.g1')::uuid,'Ignored',null,null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000006','',100)::text,true);
select is((select guest_id from public.reservations where id=(current_setting('test.returnwalk')::jsonb->>'id')::uuid),current_setting('test.g1')::uuid,'returning walk-in reuses the guest profile');
select is(current_setting('test.returnwalk')::jsonb->>'status','checked_in','returning walk-in is checked in directly');
reset role;
insert into public.whatsapp_journey_settings(property_id,enabled,required_documents)values(:'pid',true,1);
set local role authenticated;
select set_config('test.pending',public.frontdesk_walk_in(:'pid','INR','f1067000-0000-0000-0000-000000000002',null,'Documents Pending',null,null,:'type',current_date,current_date+1,1,0,null,'f1064000-0000-0000-0000-000000000005','',100)::text,true);
select is(current_setting('test.pending')::jsonb->>'status','confirmed','walk-in retains one booking when documents need approval');
select ok(current_setting('test.pending')::jsonb->>'admission_error'like '%documents%','walk-in explains document blocker');
select is((select count(*)::int from public.reservations where creation_request_id='f1067000-0000-0000-0000-000000000002'),1,'blocked walk-in does not create duplicate bookings');
select set_config('test.docsbatch',public.frontdesk_bulk_action(:'pid',gen_random_uuid(),'check_in',jsonb_build_array(jsonb_build_object('id',current_setting('test.r3'),'version',1)))::text,true);
select ok(current_setting('test.docsbatch')::jsonb#>>'{0,error}'like '%documents%','bulk admission preserves required document approval');
reset role;
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,credentials_ref)values('f1068000-0000-0000-0000-000000000001',:'tenant',:'pid','99106001','99106002','local-no-token');
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id,guest_id,last_inbound_at)values('f1069000-0000-0000-0000-000000000001',:'tenant',:'pid','f1068000-0000-0000-0000-000000000001','15550001061',current_setting('test.g1')::uuid,now());
insert into public.whatsapp_guest_authorizations(property_id,tenant_id,guest_id,wa_contact_id,conversation_id,status,evidence)values(:'pid',:'tenant',current_setting('test.g1')::uuid,'15550001061','f1069000-0000-0000-0000-000000000001','granted','Local test agreement');
insert into public.guest_access_tokens(tenant_id,property_id,reservation_id,token_hash,expires_at)values(:'tenant',:'pid',current_setting('test.r1')::uuid,'phone-correction-test',now()+interval '1 day');
insert into private.whatsapp_consent_challenges(property_id,reservation_id,guest_id,connection_id,phone,portal_token_hash,code_hash,request_id,marketing)values(:'pid',current_setting('test.r1')::uuid,current_setting('test.g1')::uuid,'f1068000-0000-0000-0000-000000000001','15550001061','phone-correction-test','phone-correction-code',gen_random_uuid(),false);
insert into public.messages(id,tenant_id,property_id,conversation_id,direction,type,body,status)values('f106a000-0000-0000-0000-000000000001',:'tenant',:'pid','f1069000-0000-0000-0000-000000000001','out','text','Private old message','sending');
set local role authenticated;
select throws_ok(format('select public.frontdesk_edit_guest(%L,%L,2,''Corrected Guest'',''+15550001069'',null,''Phone correction'',true)',:'pid',current_setting('test.g1')),'22023',null,'in-flight private message blocks phone correction');
reset role;update public.messages set status='queued'where id='f106a000-0000-0000-0000-000000000001';set local role authenticated;
select lives_ok(format('select public.frontdesk_edit_guest(%L,%L,2,''Corrected Guest'',''+15550001069'',null,''Phone correction'',true)',:'pid',current_setting('test.g1')),'phone can be corrected safely');
reset role;
select is((select phone from public.guests where id=current_setting('test.g1')::uuid),'+15550001069','new phone is saved');
select is((select guest_id from public.conversations where id='f1069000-0000-0000-0000-000000000001'),null::uuid,'old number no longer exposes guest identity');
select is((select count(*)::int from public.whatsapp_guest_authorizations where guest_id=current_setting('test.g1')::uuid),0,'old permission is not transferred');
select is((select status from public.messages where id='f106a000-0000-0000-0000-000000000001'),'failed','queued message to old number is cancelled');
select ok((select revoked_at is not null from public.guest_access_tokens where token_hash='phone-correction-test'),'old private helper link is revoked');
select is((select count(*)::int from public.reservations where guest_id=current_setting('test.g1')::uuid),2,'phone correction preserves booking history');
select ok((select cancelled_at is not null from private.whatsapp_consent_challenges where code_hash='phone-correction-code'),'phone correction cancels old confirmation challenges');
select ok(exists(select 1 from private.guest_identity_audit where guest_id=current_setting('test.g1')::uuid and action='guest_details_updated'),'guest corrections are audited');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1060000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok(format('select public.frontdesk_edit_guest(%L,%L,3,''Unauthorized Guest'',null,null,''Unauthorized correction'')',:'pid',current_setting('test.g1')),'42501',null,'ordinary member cannot edit a guest');
select throws_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''check_in'',%L::jsonb)',:'pid',current_setting('test.items')),'42501',null,'ordinary member cannot run bulk admission');
select throws_ok(format('select public.frontdesk_walk_in(%L,''INR'',gen_random_uuid(),null,''Unauthorized walk-in'',null,null,%L,current_date,current_date+1,1,0,null,null,'''',100)',:'pid',:'type'),'42501',null,'walk-in requires booking and front desk rights');
reset role;set local role anon;
select throws_ok(format('select public.frontdesk_bulk_action(%L,gen_random_uuid(),''check_in'',''[]'')',:'pid'),'42501',null,'anonymous callers cannot run batch commands');
select *from finish();
rollback;
